        assertThat(template.outputSchemaVersion()).isEqualTo("inventory-analysis-output-v1");
        assertThat(template.taskPrompt()).contains("suggestedQuantity");
        assertThat(template.taskPrompt()).contains("PENDING_REVIEW");
