/**
 * Guards the manually applied migration set in docs/sql/migrations: every
 * file must follow the V{n}__{snake_case}.sql convention and the version
 * numbers must stay unique and contiguous so the documented apply order
 * (sort -V) is unambiguous.
 */
class MigrationVersionOrderTest {

    private static final Pattern MIGRATION_FILE = Pattern.compile("V(\\d+)__[a-z0-9_]+\\.sql");

    @Test
    void migrationVersionsAreUniqueAndContiguous() throws IOException {
        Path migrationsDir = locateMigrationsDir();
        List<String> sqlFileNames;
        try (Stream<Path> files = Files.list(migrationsDir)) {
            sqlFileNames = files
                    .map(path -> path.getFileName().toString())
                    .filter(name -> name.endsWith(".sql"))
                    .toList();
        }
        assertThat(sqlFileNames).isNotEmpty();

        List<Integer> versions = sqlFileNames.stream()
                .map(name -> {
                    Matcher matcher = MIGRATION_FILE.matcher(name);
                    assertThat(matcher.matches())
                            .as("migration file name %s must match V{n}__{snake_case}.sql", name)
                            .isTrue();
                    return Integer.parseInt(matcher.group(1));
                })
                .sorted()
                .toList();

        assertThat(versions)
                .as("migration versions must be unique and contiguous starting at V1")
                .containsExactlyElementsOf(IntStream.rangeClosed(1, versions.size()).boxed().toList());

